import 'dart:async';import 'dart:convert';import 'dart:io';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/data_controls.dart';
void main(){final f=jsonDecode(File('test/data_controls/model-fixtures.json').readAsStringSync()) as Map<String,Object?>;
 test('TypeScript/Dart shared window, field and URL oracle',(){
 final windows=(f['windows'] as List).cast<List<Object?>>(),expected=(f['windowExpected'] as List).cast<Map<String,Object?>>();
 for(var i=0;i<windows.length;i++){final a=windows[i],w=virtualWindow(a[0] as int,(a[1] as num).toDouble(),(a[2] as num).toDouble(),(a[3] as num).toDouble());expect({'start':w.start,'end':w.end,'before':w.before,'after':w.after},expected[i]);}
 for(final row in (f['fields'] as List).cast<List<Object?>>()){final c=row[1] as Map<String,Object?>;expect(fieldError(row[0] as String,c['kind'] as String,required:c['required']==true,min:(c['min'] as num?)?.toDouble(),max:(c['max'] as num?)?.toDouble(),step:(c['step'] as num?)?.toDouble(),pattern:c['pattern'] as String?),row[2]);}
 for(final row in (f['urls'] as List).cast<List<Object?>>()){if(row[1]==true){expect(safeHttps(row[0]),row[0]);}else{expect(()=>safeHttps(row[0]),throwsArgumentError);}}});
 test('50000 row projection and identity pruning',(){final m=DataTableModel([DataColumnSpec('n','Number',120),DataColumnSpec('text','Text',150)],List.generate(50000,(i)=>DataRowSpec('r$i',{'n':50000-i,'text':'row $i'})),pageSize:1000);m.sort('n');expect(m.pageRows().rows.first.id,'r49999');m.toggle('r1');m.filter('row 1');expect(m.selected,contains('r1'));m.configure('n',pinned:true,width:180,minWidth:80,maxWidth:400);m.configure('text',move:-1,minWidth:80,maxWidth:400);expect(m.visible().first.key,'n');expect(()=>m.configure('n',width:double.nan,minWidth:80,maxWidth:400),throwsArgumentError);m.replace([DataRowSpec('new',{'n':null})]);expect(m.selected,isEmpty);expect(()=>m.replace([DataRowSpec('a',{}),DataRowSpec('a',{})]),throwsArgumentError);});
 test('structured document allowlist and literal text',(){final d={'version':1,'blocks':[{'text':'<script>bad()</script>','bold':true,'italic':false,'kind':'bullet','link':'https://example.org'}]};expect(validateDocument(d),d);expect(()=>validateDocument({...d,'html':'bad'}),throwsArgumentError);expect(()=>validateDocument({'version':1,'blocks':[{'text':'a'*32769,'bold':false,'italic':false,'kind':'paragraph'}]}),throwsArgumentError);expect(formatMask('123456','###-###'),'123-456');});
 const p=UploadPolicy(maxFiles:2,maxBytes:100,types:['text/plain']),file=UploadCandidate('a.txt',5,'text/plain','opaque');
 test('upload denial, cancellation, stable retry and durable receipt',()async{var pending=Completer<String>();final keys=<String>[];void Function(double)? progress;final t=UploadTask('session',p,retrySafe:true,port:(scope,key,files,cancel,report){keys.add(key);progress=report;return pending.future;});t.choose([file]);final first=t.send();progress!(0.5);progress!(0.2);expect(t.progress,0.5);t.cancel();pending.complete('late');await first;expect(t.status,'cancelled');pending=Completer<String>();final retry=t.send();pending.complete('durable');await retry;expect(t.receiptId,'durable');expect(keys[0],keys[1]);expect(()=>t.choose([const UploadCandidate('../a',5,'text/plain','x')]),throwsArgumentError);expect(t.files,isEmpty);t.dispose();});
 test('unbound upload and missing acknowledgement cannot become success',()async{final t=UploadTask('scope',p);t.choose([file]);await t.send();expect(t.status,'ready');t.dispose();final denied=UploadTask('scope2',p,port:(a,b,c,d,e)async=>'');denied.choose([file]);await denied.send();expect(denied.status,'error');denied.dispose();});
}
